<?php
declare(strict_types=1);

require_once dirname(__DIR__) . '/config.php';
exigirAdmin();

$erro='';$sucesso='';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!validarCsrf($_POST['csrf_token']??null)){$erro='A solicitação expirou.';}else{try{$acao=(string)($_POST['acao']??'adicionar');$id=(int)($_POST['competencia_id']??0);if($acao==='excluir'){$stmt=$pdo->prepare('DELETE FROM competencias WHERE id=?');$stmt->execute([$id]);$sucesso='Competência removida.';}else{$treinamentoId=(int)($_POST['treinamento_id']??0);$descricao=trim((string)($_POST['descricao']??''));$ordem=max(1,(int)($_POST['ordem']??1));if($treinamentoId<1||mb_strlen($descricao)<3){$erro='Informe o treinamento e a competência.';}else{$stmt=$pdo->prepare('INSERT INTO competencias (treinamento_id,descricao,ordem) VALUES (?,?,?)');$stmt->execute([$treinamentoId,$descricao,$ordem]);registrarAtividade($pdo,(int)$_SESSION['usuario_id'],'adicionou uma competência',$descricao);$sucesso='Competência cadastrada.';}}}catch(Throwable $e){registrarErro($pdo,'gerenciamento de competencias',$e);$erro='Não foi possível concluir a operação.';}}}
$treinamentos=$pdo->query('SELECT id,titulo FROM treinamentos ORDER BY titulo')->fetchAll();$competencias=$pdo->query('SELECT c.id,c.descricao,c.ordem,t.titulo AS treinamento_titulo FROM competencias c JOIN treinamentos t ON t.id=c.treinamento_id ORDER BY t.titulo,c.ordem')->fetchAll();
?><!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TrainHub - Competências</title><link rel="stylesheet" href="css/app.css?v=1.0"></head><body><header class="th-topbar"><a class="th-logo" href="dashboard.php"><img src="assets/logo.png" alt="TrainHub"></a><a class="th-avatar" href="perfil.php">●</a></header><main class="th-shell"><a class="th-back" href="dashboard.php">←</a><div class="th-heading"><div><h1>Competências</h1><p>Defina os resultados de aprendizagem de cada treinamento.</p></div></div><?php if($erro):?><p class="th-alert th-alert-error"><?php echo esc($erro);?></p><?php endif;?><?php if($sucesso):?><p class="th-alert th-alert-success"><?php echo esc($sucesso);?></p><?php endif;?><div class="th-grid"><section class="th-panel"><div class="th-list"><?php if(!$competencias):?><p class="th-empty">Nenhuma competência cadastrada.</p><?php endif;?><?php foreach($competencias as $competencia):?><article class="th-card th-card-row"><div><span class="th-meta"><?php echo esc($competencia['treinamento_titulo']);?></span><strong><?php echo (int)$competencia['ordem'];?>. <?php echo esc($competencia['descricao']);?></strong></div><form method="post" onsubmit="return confirm('Remover esta competência?')"><?php echo csrfInput();?><input type="hidden" name="acao" value="excluir"><input type="hidden" name="competencia_id" value="<?php echo (int)$competencia['id'];?>"><button class="th-button th-button-danger">Remover</button></form></article><?php endforeach;?></div></section><aside class="th-panel"><h2>Nova competência</h2><form class="th-form" method="post"><?php echo csrfInput();?><input type="hidden" name="acao" value="adicionar"><label class="th-field">Treinamento<select name="treinamento_id" required><option value="">Selecione</option><?php foreach($treinamentos as $treinamento):?><option value="<?php echo (int)$treinamento['id'];?>"><?php echo esc($treinamento['titulo']);?></option><?php endforeach;?></select></label><label class="th-field">Descrição<textarea name="descricao" required></textarea></label><label class="th-field">Ordem<input name="ordem" type="number" min="1" value="1"></label><button class="th-button">Cadastrar competência</button></form></aside></div></main></body></html>
